const content = $input.first().json.choices[0].message.content.trim();
let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  const match = content.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : content);
}
return { json: { success: true, data: parsed } };
